pub struct Solution;

impl Solution {
    pub fn first_missing_positive(nums: Vec<i32>) -> i32 {
        let mut nums = nums;
        let n = nums.len();

        for i in 0..n {
            while nums[i] > 0 && (nums[i] as usize) <= n {
                let target_idx = (nums[i] - 1) as usize;
                if nums[target_idx] == nums[i] {
                    break;
                }
                nums.swap(i, target_idx);
            }
        }

        for (i, &num) in nums.iter().enumerate() {
            if num != (i + 1) as i32 {
                return (i + 1) as i32;
            }
        }

        (n + 1) as i32
    }
}

